#!/usr/bin/env node
/**
 * Refresh docs/assets/how-molecule-works-{dark,light}.svg — the animated
 * graphic at the top of README.md — from its source of truth.
 *
 * The graphic is generated by, and served from, the "How Molecule works" site
 * (https://github.com/molecule-dev/how-molecule-works — a molecule.dev static
 * project, deployed at https://how-molecule-works.apps.mlcl.dev). Every build of
 * that site regenerates the SVGs; this repo only carries copies so the README
 * renders from a relative path. Run this after the site deploys, then commit:
 *
 *   node scripts/sync-readme-animation.mjs             # from the live site
 *   node scripts/sync-readme-animation.mjs --from DIR   # from a local checkout's app/public
 *   node scripts/sync-readme-animation.mjs --check      # exit 1 if the copies differ
 */

import console from 'node:console'
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import process from 'node:process'
import { fileURLToPath } from 'node:url'

const HERE = dirname(fileURLToPath(import.meta.url))
const ASSETS = join(HERE, '..', 'docs', 'assets')
const SITE = 'https://how-molecule-works.apps.mlcl.dev'
const FILES = ['how-molecule-works-dark.svg', 'how-molecule-works-light.svg']

const args = process.argv.slice(2)
const check = args.includes('--check')
const fromIdx = args.indexOf('--from')
const fromDir = fromIdx >= 0 ? args[fromIdx + 1] : null

/** The current source copy of one file, from the local checkout or the live site. */
async function source(name) {
  if (fromDir) return readFileSync(join(fromDir, name), 'utf8')
  const res = await fetch(`${SITE}/${name}`, { signal: AbortSignal.timeout(30_000) })
  if (!res.ok) throw new Error(`${SITE}/${name} → ${res.status}`)
  return res.text()
}

let changed = 0
for (const name of FILES) {
  const next = await source(name)
  if (!next.includes('<svg')) throw new Error(`${name}: not an SVG`)
  const target = join(ASSETS, name)
  let current = ''
  try {
    current = readFileSync(target, 'utf8')
  } catch (_error) {
    // A missing copy is simply out of date.
  }
  if (current === next) {
    console.log(`${name}: in sync`)
    continue
  }
  changed++
  if (check) {
    console.log(`${name}: DIFFERS from ${fromDir ?? SITE}`)
  } else {
    writeFileSync(target, next)
    console.log(`${name}: updated (${(next.length / 1024).toFixed(0)} KB)`)
  }
}
if (check && changed) {
  console.error(
    `README animation out of sync (${changed} file(s)) — run scripts/sync-readme-animation.mjs and commit`,
  )
  process.exit(1)
}
